import { TACTIC_META } from "@/services/investigationService";
import { unexploredGoals } from "@/services/strategyService";
import type { CaseRuntime, Investigation } from "@/types/investigation";
import { truncate } from "@/utils/formatters";

/**
 * Case summary built strictly from the recorded conversation and analysis —
 * generated by the local analysis engine over real session events.
 */

export interface SummaryMoment {
  timestamp: number;
  label: string;
  text: string;
}

export interface CaseSummary {
  scenario: string;
  tactics: string;
  payment: string;
  moments: SummaryMoment[];
}

function firstScammerMessage(runtime: CaseRuntime) {
  return runtime.messages.find((m) => m.author === "scammer");
}

export function buildCaseSummary(
  investigation: Investigation,
  runtime: CaseRuntime,
): CaseSummary {
  const opening = firstScammerMessage(runtime);
  const scenario = [
    investigation.description,
    opening ? `Opening line: “${truncate(opening.text, 160)}”` : "",
  ]
    .filter(Boolean)
    .join(" ");

  const counts = new Map<string, number>();
  for (const t of runtime.tactics) {
    const name = TACTIC_META[t.tactic]?.name ?? t.tactic;
    counts.set(name, (counts.get(name) ?? 0) + 1);
  }
  const tactics =
    counts.size > 0
      ? Array.from(counts.entries())
          .map(([name, n]) => `${name} (×${n})`)
          .join(", ")
      : "No tactics were detected in this session.";

  const payments = runtime.evidence.filter(
    (e) => e.type === "payment_request" || e.type === "upi",
  );
  const payment =
    payments.length > 0
      ? payments.map((e) => `${e.label}: ${e.value}`).join(" · ")
      : "No payment demand or payment identifier was captured.";

  const moments: SummaryMoment[] = runtime.stages
    .filter((s) => s.status !== "pending" && s.detectedAt)
    .map((s) => {
      const msg = runtime.messages.find((m) =>
        s.messageIds.includes(m.id),
      );
      return {
        timestamp: s.detectedAt ?? msg?.timestamp ?? investigation.createdAt,
        label: s.label,
        text: msg ? truncate(msg.text, 140) : s.reason,
      };
    });

  return { scenario, tactics, payment, moments };
}

/** What this investigation never established — honest, data-derived gaps. */
export function buildUnknowns(
  investigation: Investigation,
  runtime: CaseRuntime,
): string[] {
  const unknowns: string[] = [];
  unknowns.push(...unexploredGoals(runtime));
  if (runtime.status !== "completed") {
    unknowns.push("Conversation was still active when the session was snapshotted.");
  }
  if (!runtime.evidence.some((e) => e.type === "upi"))
    unknowns.push("No payment identifier (UPI/VPA) was captured.");
  if (!runtime.evidence.some((e) => e.type === "url"))
    unknowns.push("No suspicious URL was captured.");
  if (!runtime.evidence.some((e) => e.type === "phone"))
    unknowns.push("No phone number identifier was captured.");
  unknowns.push(
    "All identifiers are synthetic demo values — no external verification, lookup or tracing was performed.",
  );
  void investigation;
  return unknowns;
}
